// pnpm gen:db-types / pnpm gen:api-types (BL-0010): regenerate packages/shared-types.
//   db:  `supabase gen types typescript --local --schema public` from the migrated local database
//   api: openapi-typescript from polymath-app-spec/schemas/api.openapi.yaml
// The generated files are committed; CI regenerates them and fails on any difference
// (git diff --exit-code packages/shared-types). Never edit them by hand.
import { execFileSync } from "node:child_process";
import { writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
const OUT = path.join(ROOT, "packages", "shared-types", "src");
const OPENAPI = path.join(ROOT, "polymath-app-spec", "schemas", "api.openapi.yaml");
const HEADER = (source) =>
  `// GENERATED by pnpm gen:${source} (tools/gen/gen-types.mjs). Do not edit by hand.\n`;

function bin(name) {
  return path.join(ROOT, "node_modules", ".bin", name);
}

function genDb() {
  const out = execFileSync(bin("supabase"), ["gen", "types", "typescript", "--local", "--schema", "public"], {
    cwd: ROOT,
    encoding: "utf8",
    maxBuffer: 64 * 1024 * 1024,
  });
  writeFileSync(path.join(OUT, "database.gen.ts"), HEADER("db-types") + out);
  console.log("wrote packages/shared-types/src/database.gen.ts");
}

function genApi() {
  const out = execFileSync(bin("openapi-typescript"), [OPENAPI], {
    cwd: ROOT,
    encoding: "utf8",
    maxBuffer: 64 * 1024 * 1024,
  });
  writeFileSync(path.join(OUT, "api.gen.ts"), HEADER("api-types") + out);
  console.log("wrote packages/shared-types/src/api.gen.ts");
}

const which = process.argv[2];
if (which === "db") genDb();
else if (which === "api") genApi();
else {
  console.error("usage: node tools/gen/gen-types.mjs db|api");
  process.exit(2);
}
